/**
 * Primary key generation — OD-12.
 *
 * UUID v7, generated by the application, never by the database. Every
 * `.create()` call across this codebase supplies `id: generateId()` itself;
 * no model in schema.prisma declares `@default(...)` on `id`, so a create
 * that forgets this fails loudly (a NOT NULL violation) instead of silently
 * falling back to a database-generated id OD-12 rejected.
 */

import { uuidv7 } from 'uuidv7';

export function generateId(): string {
  return uuidv7();
}
